Found by Linux Verification Center (linuxtesting.org).

Fixes: c8cb5b854b40 ("nl80211/cfg80211: support 6 GHz scanning")
Signed-off-by: Fedor Pchelkin <pchelkin@ispras.ru>
Link: https://patch.msgid.link/20260601094157.92703-1-pchelkin@ispras.ru
Signed-off-by: Johannes Berg <johannes.berg@intel.com>

Here is the root cause:
In cfg80211_scan(), the assignment `rdev->int_scan_req = request` was performed before calling `rdev_scan()`. If `rdev_scan()` fails, the function returns an error, but the allocated `request` is already stored in `rdev->int_scan_req`. The freeing mechanism in `___cfg80211_scan_done()` does not execute because `rdev->scan_req` is NULL, leaving the memory leaked.

Here is the patch:

 int cfg80211_scan(struct cfg80211_registered_device *rdev)
 {
 	struct cfg80211_scan_request_int *request;
 	struct cfg80211_scan_request_int *rdev_req = rdev->scan_req;
 	u32 n_channels = 0, idx, i;
+	int err;

 	if (!(rdev->wiphy.flags & WIPHY_FLAG_SPLIT_SCAN_6GHZ)) {
 		rdev_req->req.first_part = true;
 		return rdev_scan(rdev, rdev_req);
 	}

 	for (i = 0; i < rdev_req->req.n_channels; i++) {
 		if (rdev_req->req.channels[i]->band != NL80211_BAND_6GHZ)
 			n_channels++;
 	}

 	if (!n_channels)
 		return cfg80211_scan_6ghz(rdev, true);

 	request = kzalloc_flex(*request, req.channels, n_channels);
 	if (!request)
 		return -ENOMEM;

 	*request = *rdev_req;
 	request->req.n_channels = n_channels;

 	for (i = idx = 0; i < rdev_req->req.n_channels; i++) {
 		if (rdev_req->req.channels[i]->band != NL80211_BAND_6GHZ)
 			request->req.channels[idx++] =
 				rdev_req->req.channels[i];
 	}

 	rdev_req->req.scan_6ghz = false;
 	rdev_req->req.first_part = true;
+	err = rdev_scan(rdev, request);
+	if (err) {
+		kfree(request);
+		return err;
+	}
+
 	rdev->int_scan_req = request;
-	return rdev_scan(rdev, request);
+	return 0;
 }



